from pathlib import Path
import yaml,hashlib,re
R=Path.cwd()
def read(p): return yaml.safe_load((R/p).read_text(encoding='utf8'))
def write(p,obj): (R/p).write_text(yaml.safe_dump(obj,allow_unicode=True,sort_keys=False,width=110),encoding='utf8')
# chapter metadata correction
chs=read('metadata/chapters.yaml'); c=next(x for x in chs if x['chapter_id']=='CH13'); c.update(title_en='Mise-en-scène: Space, Blocking, and Eyelines (working title)',zh_status='review-needed',en_status='review-needed'); write('metadata/chapters.yaml',chs)
# Append BibTeX records without touching existing entries
bib=R/'metadata/references.bib'; text=bib.read_text(encoding='utf8')
entries=["@book{R094, author = {John Gibbs}, title = {Mise-en-scène: Film Style and Interpretation}, publisher = {Wallflower Press}, year = {2002}, isbn = {9781903364062}, url = {https://cup.columbia.edu/book/mise-en-scene/9781903364062/}, note = {Publisher page only; full text/page locators unverified; accessed 2026-10-22}}", "@incollection{R095, author = {Andrew Dix}, title = {Seeing film: Mise-en-scène}, booktitle = {Beginning Film Studies}, edition = {2}, publisher = {Manchester University Press}, pages = {12--45}, doi = {10.7765/9781784997304.00008}, url = {https://www.cambridge.org/core/books/abs/beginning-film-studies-second-edition/italicseeing-filmitalic-miseenscene/159D0ABB39DFCDD99E7BCAF32E42DD99}, note = {Publisher summary only; accessed 2026-10-22}}", "@misc{R096, author = {{ScreenSkills}}, title = {Production designer skills}, url = {https://www.screenskills.com/skills-checklists/scripted-film-and-tv/art-department/production-designer-skills/}, note = {Undated UK role profile; accessed 2026-10-22}}", "@misc{R097, author = {{Skillset}}, title = {Direct the actors (drama)}, howpublished = {UK National Occupational Standard SKSDIRD8 v1}, year = {2003}, url = {https://www.ukstandards.org.uk/PublishedNos-old/SKSDIRD8.pdf}, note = {Historical standard, not universal current law; accessed 2026-10-22}}", "@misc{R098, author = {Inkoo Kang}, title = {Parasite: Notes from the Underground}, howpublished = {Criterion Collection}, date = {2020-10-30}, url = {https://www.criterion.com/current/posts/7158-parasite-notes-from-the-underground}, note = {Critical film-form interpretation; accessed 2026-10-22}}", "@misc{R099, author = {Brad Stevens}, title = {Keeping a distance: Chantal Akerman’s Jeanne Dielman}, howpublished = {Sight and Sound, BFI}, url = {https://www.bfi.org.uk/sight-and-sound/features/keeping-distance-chantal-akermans-jeanne-dielman}, note = {Critical analysis; publication metadata not verified; accessed 2026-10-22}}", "@misc{R100, author = {Brad Stevens}, title = {Reflections on style: what became of classical Hollywood mise en scène?}, howpublished = {Sight and Sound, BFI}, url = {https://www.bfi.org.uk/sight-and-sound/features/reflections-style-what-became-classical-hollywood-mise-en-scene}, note = {Critical argument, not universal rule; accessed 2026-10-22}}"]
for row in entries:
 m=re.search(r'\{(R\d+),',row)
 if m and f'{{{m.group(1)},' not in text: text+='\n\n'+row+'\n'
bib.write_text(text,encoding='utf8')
# Human review and provenance records
(R/'assets/chapters/CH13/CH13-SOURCE-AND-CASE-NOTES.md').write_text('''# CH13 Source and Case Notes\n\nResearch access date: 2026-10-22 (Asia/Taipei). The notes below limit claims to the pages actually inspected; they do not claim full-book reading or first-hand film viewing.\n\n| ID | Evidence inspected | Permitted use | Open verification |\n|---|---|---|---|\n| R094 | Columbia University Press bibliographic/contents page for John Gibbs, 2002 book | Bibliographic metadata and broad scope | Consult accessible book edition and record page locators before attributing detailed arguments. |\n| R095 | Manchester UP chapter page/abstract; pp. 12–45 listed | Summary-level scope of mise-en-scène and related cinematic choices | Verify exact wording and page locators in chapter text. |\n| R096 | ScreenSkills production-designer role profile | UK role collaboration/scope only | Undated; confirm current role profile before time-sensitive use. |\n| R097 | Archived UK NOS SKSDIRD8, approved 2003 | Historical role/process example only | Find successor standard and confirm jurisdiction; do not present as current legal rule. |\n| R098 | Criterion Collection essay by Inkoo Kang, 2020-10-30 | Attribute spatial interpretation to essay author | Verify film edition and shot/timecode only after lawful viewing. |\n| R099 | BFI/Sight and Sound essay by Brad Stevens | Attribute discussion of Akerman’s spatial form to critic | Article metadata and exact film editions/timecodes remain unverified. |\n| R100 | BFI/Sight and Sound critical essay by Brad Stevens | Attribute argument about style to author | Verify metadata and context; do not generalize as universal production method. |\n\nNo film timecodes, production credits, or first-hand viewing claims have been invented.\n''',encoding='utf8')
(R/'assets/chapters/CH13/CH13-HUMAN-REVIEW-CHECKLIST.md').write_text('''# CH13 Human Review Checklist\n\nStatus: all items below remain open; this is not a sign-off.\n\n- [ ] Author: approve scope, Traditional Chinese terminology, examples, exercises, and working English title.\n- [ ] Bilingual editor: review every aligned section, captions, and terminology for meaning and natural usage.\n- [ ] Film theory specialist: validate the boundaries/history of mise-en-scène and the critical readings.\n- [ ] Production specialist: test floor-plan workflow, role descriptions, camera/axis examples, and safety/feasibility checks.\n- [ ] Film researcher: verify legal viewing editions and add edition-specific timecodes only after viewing.\n- [ ] Rights reviewer: assess SVG originality, similarity, creator attribution, license, accessibility, and publication permission.\n- [ ] Publisher/author: proof final site and book pages and record publication approval.\n\nUntil signed, manuscripts remain review-needed and figures remain pending; the chapter is not publication-ready.\n''',encoding='utf8')
# Figure rights/source log
(R/'assets/chapters/CH13/CH13-FIGURE-RIGHTS-AND-SOURCES.md').write_text('''# CH13 Figure Rights and Sources\n\nBoth assets are hand-authored editable SVG schematics created 2026-10-22 for instruction. No AI image model, web image, movie still, character likeness, logo, or traced film composition was used. Conceptual references are listed in `figure-manifest.yaml`; they inform general analytical categories only.\n\n| Figure | Asset | SHA-256 | Status | Open checks |\n|---|---|---|---|---|\n'''+''.join(f"| {x['figure_id']} | `{x['asset_original']}` | `{x['sha256']}` | draft-original-svg / pending-publication-approval | Creator attribution, similarity, accessibility, technical and editorial review, rights and author approval |\n" for x in read('assets/chapters/CH13/figure-manifest.yaml')['figures'])+'\n',encoding='utf8')
