p=R/'CHAPTER_INTEGRATION_MATRIX.md'; t=p.read_text(encoding='utf8'); lines=t.splitlines()
for i,line in enumerate(lines):
 if line.startswith('| CH13｜'):
  lines[i]='| CH13｜場面調度：空間、動線與視線 | PARTIAL | PARTIAL | PARTIAL | PARTIAL | MISSING | MISSING | PARTIAL | PARTIAL | 研究草稿已建立；來源定位、雙語校譯、案例觀片與圖稿權利待審 |'
  break
